import subprocess,re
def blob(rev,f): return subprocess.run(['git','show',rev+':'+f],capture_output=True,text=True).stdout.split('\n')
def spans(lines):
    idx=[i for i,L in enumerate(lines,1) if re.match(r'^\d+\. \*\*',L)]
    heads=[i for i,L in enumerate(lines,1) if L.startswith('#')]
    out={}
    for k,st in enumerate(idx):
        nxt=[j for j in idx if j>st]+[j for j in heads if j>st]
        end=(min(nxt)-1) if nxt else len(lines)
        n=int(re.match(r'^(\d+)\.',lines[st-1]).group(1)); out[n]=(st,end)
    return out
